<template><div class="page"><h2 class="page-title">生成个性化预算</h2><div class="card section"><div class="actions"><el-select v-model="goalId" placeholder="选择目标"><el-option v-for="g in goals" :key="g.id" :label="`${formatMoney(g.target_savings_minor)} / ${g.target_date}`" :value="g.id"/></el-select><el-radio-group v-model="mode"><el-radio-button value="goal_priority">储蓄目标优先</el-radio-button><el-radio-button value="balanced">平衡模式</el-radio-button><el-radio-button value="life_stability">生活稳定优先</el-radio-button></el-radio-group><el-button type="primary" :loading="loading" @click="generate">生成候选方案</el-button></div><el-alert class="section" title="默认使用平衡模式。系统先判断可行性，再调用阶段7优化器。" type="info" :closable="false"/></div><template v-if="result"><div v-if="result.feasible" class="grid section"><div class="card"><span class="muted">自然消费</span><div class="metric">{{formatMoney(result.natural_spending_minor)}}</div></div><div class="card"><span class="muted">推荐预算</span><div class="metric">{{formatMoney(result.recommended_spending_minor)}}</div></div><div class="card"><span class="muted">预计期末存款</span><div class="metric">{{formatMoney(result.expected_final_savings_minor)}}</div></div><div class="card"><span class="muted">情景风险</span><div class="metric">{{result.risk_level}}</div><small>不是成功概率</small></div></div><el-result v-else icon="warning" title="当前目标不可行" :sub-title="`当前期限最高目标 ${formatMoney(result.maximum_achievable_target_minor)}，额外收入需求 ${formatMoney(result.required_additional_income_minor)}`"/><div class="card section" v-if="result.items?.length"><h3>自然消费基线 vs 推荐预算</h3><EChart :option="chart"/><el-table :data="categoryRows"><el-table-column prop="category" label="类别"/><el-table-column label="自然消费"><template #default="s">{{formatMoney(s.row.natural)}}</template></el-table-column><el-table-column label="推荐预算"><template #default="s">{{formatMoney(s.row.budget)}}</template></el-table-column><el-table-column label="调整"><template #default="s">{{formatMoney(s.row.delta)}}</template></el-table-column></el-table><h3 class="section">自然月汇总</h3><el-table :data="result.monthly_plan"><el-table-column prop="year_month" label="月份"/><el-table-column label="预计收入"><template #default="s">{{formatMoney(s.row.expected_income_minor)}}</template></el-table-column><el-table-column label="自然消费"><template #default="s">{{formatMoney(s.row.natural_consumption_minor)}}</template></el-table-column><el-table-column label="推荐消费"><template #default="s">{{formatMoney(s.row.recommended_consumption_minor)}}</template></el-table-column><el-table-column label="预计储蓄"><template #default="s">{{formatMoney(s.row.expected_saving_minor)}}</template></el-table-column><el-table-column label="累计存款"><template #default="s">{{formatMoney(s.row.cumulative_savings_minor)}}</template></el-table-column></el-table><el-button class="section" type="primary" @click="activate">确认并激活计划</el-button></div></template></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js';import EChart from '../components/EChart.vue'
const goals=ref([]),goalId=ref(),mode=ref('balanced'),result=ref(),loading=ref(false);onMounted(async()=>goals.value=(await api.get('/goals')).items)
async function generate(){loading.value=true;try{result.value=await api.post('/budgets/generate',{goal_id:goalId.value,adjustment_mode:mode.value})}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
const categoryRows=computed(()=>{const m={};for(const x of result.value?.items||[]){m[x.category_code]??={category:x.category_code,natural:0,budget:0,delta:0};m[x.category_code].natural+=x.natural_spend_minor;m[x.category_code].budget+=x.recommended_budget_minor;m[x.category_code].delta+=x.adjustment_minor}return Object.values(m)})
const chart=computed(()=>({tooltip:{trigger:'axis'},legend:{},xAxis:{type:'category',data:categoryRows.value.map(x=>x.category)},yAxis:{type:'value'},series:[{name:'自然消费',type:'bar',data:categoryRows.value.map(x=>x.natural)},{name:'推荐预算',type:'bar',data:categoryRows.value.map(x=>x.budget),color:'#2b9a72'}]}))
async function activate(){try{await api.post(`/budgets/${result.value.plan_id}/activate`);ElMessage.success('预算计划已激活')}catch(e){ElMessage.error(e.message)}}
</script>
